 const dimensions=()=>{const r=host.getBoundingClientRect(),ts=chart.timeScale();return {w:ts.width?.()||Math.max(0,r.width-60),h:chart.panes?.()[0]?.getHeight?.()||Math.max(0,r.height-(ts.height?.()||28))}};
