 $('tool').onchange=()=>choose($('tool').value);$('undo').onclick=()=>history('undo');$('redo').onclick=()=>history('redo');$('delete').onclick=remove;$('clear').onclick=()=>{const before=clone(model.drawings);model.drawings=[];selected=-1;draft=[];hover=null;push(before);message('Drawings cleared for this stock/timeframe. Undo restores them.');render()};
 const style=()=>{if(selected>=0){const before=clone(model.drawings);model.drawings[selected].color=$('color').value;model.drawings[selected].width=Number($('width').value);if(model.drawings[selected].type==='text')model.drawings[selected].text=$('text').value.trim().slice(0,100)||'Note';push(before);render()}};$('color').onchange=$('width').onchange=$('text').onchange=style;
